query:
SELECT id, questionText, questionId FROM ai_responses WHERE projectId = 1 LIMIT 10;
SELECT id, questionText, source FROM questions WHERE projectId = 1 LIMIT 15;
SELECT COUNT(*) AS totalResponses, SUM(CASE WHEN questionText IS NULL OR questionText = '' THEN 1 ELSE 0 END) AS responsesMissingQuestionText, SUM(CASE WHEN questionId IS NULL THEN 1 ELSE 0 END) AS responsesMissingQuestionId FROM ai_responses WHERE projectId = 1;
SELECT COUNT(*) AS totalAnalyses FROM analysis_results WHERE projectId = 1;
SELECT id, CHAR_LENGTH(markdownContent) AS markdownLength, LEFT(markdownContent, 120) AS preview FROM reports WHERE projectId = 1 ORDER BY createdAt DESC LIMIT 3;

